 test/addressparser/addressparser-test.ts | 127 +++++++++++++++++++++++
 test/mime-node/mime-node-test.ts         |  17 +++
 3 files changed, 241 insertions(+), 1 deletion(-)

diff --git a/src/addressparser/index.ts b/src/addressparser/index.ts
index 5bf75060..3d5e2423 100644
--- a/src/addressparser/index.ts
+++ b/src/addressparser/index.ts
@@ -679,6 +679,14 @@ class Tokenizer {
     inDomainLiteral: boolean;
     /** The last addr-spec character seen was an "@", with only whitespace or comments since */
     afterAt: boolean;
+    /** A quoted string is open inside the angle-addr or group being collected */
+    innerQuoted: boolean;
+    /** Comment depth inside the angle-addr or group being collected */
+    innerComment: number;
+    /** A domain literal is open inside the angle-addr being collected */
+    innerLiteral: boolean;
+    /** The previous character inside an inner quoted string or comment was a backslash */
+    innerEscaped: boolean;
     list: Token[];
     operators: { [operator: string]: string };

@@ -690,6 +698,10 @@ class Tokenizer {
         this.escaped = false;
         this.inDomainLiteral = false;
         this.afterAt = false;
+        this.innerQuoted = false;
+        this.innerComment = 0;
+        this.innerLiteral = false;
+        this.innerEscaped = false;

         this.list = [];
         /**
@@ -762,9 +774,20 @@ class Tokenizer {
             }
         }

+        // The closer of an angle-addr or a group is only read outside the quoted strings,
+        // comments and domain literals it holds. Looking for nothing but the closer let a '>'
+        // inside a quoted local part end the angle-addr, '<"a@evil.com>"@good.com>' was read
+        // as an address at evil.com, and a ';' inside a quoted display name or a comment end
+        // the group and release the rest of that text as recipients. The characters are still
+        // collected as they are, the angle-addr and the group content are read again later
+        let nested = false;
+        if (this.operatorExpecting === '>' || this.operatorExpecting === ';') {
+            nested = this._trackInner(chr);
+        }
+
         if (this.escaped) {
             // ignore next condition blocks
-        } else if (chr === this.operatorExpecting) {
+        } else if (chr === this.operatorExpecting && !nested) {
             this.node = {
                 type: 'operator',
                 value: chr
@@ -782,6 +805,7 @@ class Tokenizer {
             }
             this.operatorExpecting = '';
             this.escaped = false;
+            this._resetInner();

             return;
         } else if (!this.operatorExpecting && !(this.inDomainLiteral && chr === ':') && chr in this.operators) {
@@ -796,6 +820,7 @@ class Tokenizer {
             }
             this.operatorExpecting = this.operators[chr];
             this.escaped = false;
+            this._resetInner();
             return;
         } else if (['"', "'", ')'].includes(this.operatorExpecting) && chr === '\\') {
             // A backslash escapes the next character inside a quoted string and inside a
@@ -832,6 +857,77 @@ class Tokenizer {

         this.escaped = false;
     }
+
+    /**
+     * Tracks the quoted strings, comments and domain literals inside an angle-addr or a
+     * group, which the closer of either must not be read from. A backslash escapes the next
+     * character inside a quoted string and a comment. A domain literal is only tracked in an
+     * angle-addr, where it opens right after an "@" and ends at the "]". dtext holds the list
+     * separators as well, and inside the brackets they never split the list anyway. In a group
+     * they do, so a literal is not tracked there and an unclosed "[" can not swallow the
+     * recipients after it.
+     *
+     * @param chr Character from the address field
+     * @return true while the character sits inside one of them, the one that closes it included
+     */
+    _trackInner(chr: string): boolean {
+        if (this.innerEscaped) {
+            this.innerEscaped = false;
+            return true;
+        }
+        if (this.innerQuoted) {
+            if (chr === '\\') {
+                this.innerEscaped = true;
+            } else if (chr === '"') {
+                this.innerQuoted = false;
+            }
+            return true;
+        }
+        if (this.innerComment) {
+            if (chr === '\\') {
+                this.innerEscaped = true;
+            } else if (chr === '(') {
+                this.innerComment++;
+            } else if (chr === ')') {
+                this.innerComment--;
+            }
+            return true;
+        }
+        if (this.innerLiteral) {
+            if (chr === ']') {
+                this.innerLiteral = false;
+            }
+            return true;
+        }
+        if (chr === '"') {
+            this.innerQuoted = true;
+            return true;
+        }
+        if (chr === '(') {
+            this.innerComment = 1;
+            return true;
+        }
+        if (chr === '[' && this.afterAt && this.operatorExpecting === '>') {
+            this.innerLiteral = true;
+            return true;
+        }
+        // afterAt is otherwise only kept outside the operators and is cleared when one opens
+        // or ends, so inside an angle-addr it serves the literal tracked here
+        if (!_isSpaceCode(chr.charCodeAt(0))) {
+            this.afterAt = chr === '@';
+        }
+        return false;
+    }
+
+    /**
+     * Forgets what _trackInner collected, once the angle-addr or group it was collected for opens or ends
+     */
+    _resetInner(): void {
+        this.innerQuoted = false;
+        this.innerComment = 0;
+        this.innerLiteral = false;
+        this.innerEscaped = false;
+    }
 }

 /**
diff --git a/test/addressparser/addressparser-test.ts b/test/addressparser/addressparser-test.ts
index 21e0b502..ab1891b6 100644
--- a/test/addressparser/addressparser-test.ts
+++ b/test/addressparser/addressparser-test.ts
@@ -1646,4 +1646,131 @@ describe('#addressparser', () => {
             assert.deepStrictEqual(addressparser('a@b.c (x\\) y)'), [{ address: 'a@b.c', name: 'x) y' }]);
         });
     });
+
+    // The tokenizer tracks one open operator, so once '<' or ':' was open it only looked for
+    // the '>' or ';' that closes it and missed the quoted strings, comments and domain
+    // literals in between. A '>' inside a quoted local part ended the angle-addr early and
+    // the domain was read off the wreckage, and a ';' inside a quoted display name or a
+    // comment ended the group and released the rest of that text as recipients
+    describe('Closers inside an angle-addr or a group', () => {
+        it('should not close an angle-addr at a ">" inside a quoted string, a comment or a domain literal', () => {
+            for (const [input, expected] of [
+                ['<"a@evil.com>"@good.com>', [{ address: '"a@evil.com>"@good.com', name: '' }]],
+                ['<"a\\>"@good.com>', [{ address: '"a\\>"@good.com', name: '' }]],
+                ['<a@[>]>', [{ address: 'a@[>]', name: '' }]],
+                ['<a@[;"]>', [{ address: 'a@[;"]', name: '' }]],
+                ['<a@[x,y>]>', [{ address: 'a@[x,y>]', name: '' }]],
+                ['Name <"x>"@evil.com>', [{ address: '"x>"@evil.com', name: 'Name' }]],
+                ['<a@good.com(x>y)>', [{ address: 'a@good.com', name: 'x>y' }]],
+                ['<a@b((x)>)>', [{ address: 'a@b', name: '(x)>' }]],
+                ['<a@b(\\)>)>', [{ address: 'a@b', name: ')>' }]]
+            ] as [string, any][]) {
+                assert.deepStrictEqual(addressparser(input), expected, input);
+            }
+        });
+
+        it('should not end a group at a ";" inside a quoted string or a comment', () => {
+            for (const [input, expected] of [
+                [
+                    'G: (a; <evil@evil.com>) <v@victim.com>;',
+                    [{ name: 'G', group: [{ address: 'v@victim.com', name: 'a; <evil@evil.com>' }] }]
+                ],
+                [
+                    'G: "a;" "<evil@evil.com>" <v@victim.com>;',
+                    [{ name: 'G', group: [{ address: 'v@victim.com', name: 'a; <evil@evil.com>' }] }]
+                ],
+                ['G: "a;b" <x@y>;', [{ name: 'G', group: [{ address: 'x@y', name: 'a;b' }] }]],
+                ['G: "a\\";" <x@y>;', [{ name: 'G', group: [{ address: 'x@y', name: 'a";' }] }]],
+                ['G: <"a;"@good.com>;', [{ name: 'G', group: [{ address: '"a;"@good.com', name: '' }] }]]
+            ] as [string, any][]) {
+                assert.deepStrictEqual(addressparser(input), expected, input);
+            }
+        });
+
+        it('should let an escaped backslash end the quoted string it is in', () => {
+            assert.deepStrictEqual(addressparser('<"a\\\\"@b.com>, c@d.com'), [
+                { address: '"a\\\\"@b.com', name: '' },
+                { address: 'c@d.com', name: '' }
+            ]);
+            assert.deepStrictEqual(addressparser('G: "a\\\\" <x@y>; c@d.com'), [
+                { name: 'G', group: [{ address: 'x@y', name: 'a\\' }] },
+                { address: 'c@d.com', name: '' }
+            ]);
+        });
+
+        // the same reading an unclosed quoted string or comment gets outside the brackets
+        it('should read an unclosed quoted string or comment to the end of the value', () => {
+            for (const input of ['<"a@b.com>, c@d.com', '<a@b.com(x>, c@d.com', 'G: "a;, c@d.com', 'G: (a;, c@d.com']) {
+                assert.strictEqual(addressparser(input).length, 1, input);
+            }
+        });
+
+        it('should still end an angle-addr and a group at the closer outside them', () => {
+            for (const [input, expected] of [
+                [
+                    '<a@b.com>, <c@d.com>',
+                    [
+                        { address: 'a@b.com', name: '' },
+                        { address: 'c@d.com', name: '' }
+                    ]
+                ],
+                [
+                    '"x" <a@b.com>, "y" <c@d.com>',
+                    [
+                        { address: 'a@b.com', name: 'x' },
+                        { address: 'c@d.com', name: 'y' }
+                    ]
+                ],
+                [
+                    '<"x"@b.com>, <(y)c@d.com>',
+                    [
+                        { address: '"x"@b.com', name: '' },
+                        { address: 'c@d.com', name: 'y' }
+                    ]
+                ],
+                [
+                    'G: "x" <a@b.com>; c@d.com',
+                    [
+                        { name: 'G', group: [{ address: 'a@b.com', name: 'x' }] },
+                        { address: 'c@d.com', name: '' }
+                    ]
+                ],
+                ['<a@[IPv6:2001:db8::1]>', [{ address: 'a@[IPv6:2001:db8::1]', name: '' }]],
+                ['G: a@[IPv6:2001:db8::1];', [{ name: 'G', group: [{ address: 'a@[IPv6:2001:db8::1]', name: '' }] }]]
+            ] as [string, any][]) {
+                assert.deepStrictEqual(addressparser(input), expected, input);
+            }
+        });
+
+        // An unclosed '[' must not swallow the recipients after it (#1829), so a literal is not
+        // tracked in a group and a ';' inside one still ends the group. A literal holding a ';'
+        // is not something any mail system hands out. Inside an angle-addr the ',' never split
+        // the list, so the literal there runs to its ']' or to the end of the value
+        it('should still end a group at a ";" inside a domain literal', () => {
+            assert.deepStrictEqual(addressparser('G: a@[x;y];'), [
+                { name: 'G', group: [{ address: 'a@[x', name: '' }] },
+                { address: '', name: 'y]' }
+            ]);
+            assert.deepStrictEqual(addressparser('<a@[x, c@d.com>'), [{ address: 'a@[x,', name: 'c@d.com>' }]);
+        });
+
+        for (const [label, build] of [
+            ['an unclosed quoted string in an angle-addr', (count: number) => '<"' + 'a'.repeat(count)],
+            ['an unclosed quoted string in a group', (count: number) => 'G: "' + ';'.repeat(count)],
+            ['nested comments in an angle-addr', (count: number) => '<' + '('.repeat(count)],
+            ['nested comments in a group', (count: number) => 'G: ' + '('.repeat(count)],
+            ['many quoted strings in a group', (count: number) => 'G: ' + '"a;" '.repeat(count / 5) + ';']
+        ] as [string, (count: number) => string][]) {
+            it(`should tokenize ${label} in linear time`, () => {
+                const count = 400000;
+                const input = build(count);
+
+                const started = Date.now();
+                addressparser(input);
+                const elapsed = Date.now() - started;
+
+                assert.ok(elapsed < 5000, `tokenizing a ${input.length} byte value took ${elapsed}ms`);
+            });
+        }
+    });
 });
diff --git a/test/mime-node/mime-node-test.ts b/test/mime-node/mime-node-test.ts
index 2f649920..49f0042b 100644
--- a/test/mime-node/mime-node-test.ts
+++ b/test/mime-node/mime-node-test.ts
@@ -3027,6 +3027,23 @@ describe('MimeNode Tests', { timeout: 50 * 1000 }, () => {
                 assert.deepStrictEqual(mb.getEnvelope().to, [expected], recipient);
             }
         });
+
+        it('should deliver to the domain of the angle-addr when a quoted local part holds a ">"', () => {
+            const mb = new MimeNode('text/plain');
+            mb.setHeader('To', '<"a@evil.com>"@good.com>');
+
+            // the '>' can not go into RCPT TO, so it is blanked, the domain is what counts
+            assert.deepStrictEqual(mb.getEnvelope().to, ['"a@evil.com "@good.com']);
+        });
+
+        it('should not take a recipient out of a quoted string or a comment inside a group', () => {
+            for (const recipient of ['G: (a; <evil@evil.com>) <v@victim.com>;', 'G: "a;" "<evil@evil.com>" <v@victim.com>;']) {
+                const mb = new MimeNode('text/plain');
+                mb.setHeader('To', recipient);
+
+                assert.deepStrictEqual(mb.getEnvelope().to, ['v@victim.com'], recipient);
+            }
+        });
     });
     describe('UTS-46 domain encoding', () => {
         // The bundled Punycode codec maps nothing, so an ignored or mapped code point
